9	// TestConfig_ScopeSlugs verifies the shared scope predicate both backends
10	// derive their repo scoping from. The precedence rule that matters most: an
11	// explicit repo filter always wins over --all-repos (the more specific filter
12	// scopes the search) — v3 and v4 must agree on this.
13	func TestConfig_ScopeSlugs(t *testing.T) {
14		t.Parallel()
15		tests := []struct {
16			name         string
17			cfg          Config
18			wantSlugs    []string
19			wantAllRepos bool
20		}{
21			{"all-repos flag", Config{AllRepos: true}, nil, true},
22			{"repo:* filter", Config{Repos: []string{AllReposFilter}}, nil, true},
23			{"explicit repo", Config{Repos: []string{"o/r"}}, []string{"o/r"}, false},
24			{"current-repo default", Config{Owner: "o", Repo: "r"}, []string{"o/r"}, false},
25			{"explicit filter wins over --all-repos", Config{AllRepos: true, Repos: []string{"o/r"}}, []string{"o/r"}, false},
26			{"explicit filter wins over repo:*", Config{Repos: []string{"o/r", AllReposFilter}}, []string{"o/r"}, false},
27			{"explicit filters win over current repo", Config{Repos: []string{"a/b", "c/d"}, Owner: "o", Repo: "r"}, []string{"a/b", "c/d"}, false},
28			{"no scope", Config{}, nil, false},
29			{"owner without repo is no scope", Config{Owner: "o"}, nil, false},
30		}
31		for _, tt := range tests {
32			t.Run(tt.name, func(t *testing.T) {
33				t.Parallel()
34				slugs, allRepos := tt.cfg.ScopeSlugs()
35				if strings.Join(slugs, ",") != strings.Join(tt.wantSlugs, ",") || allRepos != tt.wantAllRepos {
36					t.Errorf("ScopeSlugs() = (%v, %v), want (%v, %v)", slugs, allRepos, tt.wantSlugs, tt.wantAllRepos)
37				}
38			})
39		}
40	}
41	
42	// TestResultID_RawDataFallback verifies repo/pr rows — which have no typed
43	// struct — expose the raw payload's id, so cross-cell dedup can identify the
44	// same logical result from two cells.
45	func TestResultID_RawDataFallback(t *testing.T) {
46		t.Parallel()
47	
48		var repoRow Result
49		if err := json.Unmarshal([]byte(`{"type":"repo","data":{"id":"01JREPO","name":"x"},"searchMeta":{"score":1}}`), &repoRow); err != nil {
50			t.Fatal(err)
51		}
52		if got := repoRow.ResultID(); got != "01JREPO" {
53			t.Errorf("repo ResultID() = %q, want the rawData id \"01JREPO\"", got)
54		}
55	
56		var noID Result
57		if err := json.Unmarshal([]byte(`{"type":"pr","data":{"title":"no id"},"searchMeta":{"score":1}}`), &noID); err != nil {
58			t.Fatal(err)
59		}
60		if got := noID.ResultID(); got != "" {
61			t.Errorf("pr-without-id ResultID() = %q, want \"\"", got)
62		}
63	
64		// Typed results are unaffected.
65		ck := Result{Type: TypeCheckpoint, Checkpoint: &CheckpointResult{ID: "ck1"}}
66		if got := ck.ResultID(); got != "ck1" {
67			t.Errorf("checkpoint ResultID() = %q, want \"ck1\"", got)
68		}
69	}
