71	// TestResultAccessors_RawDataFallback verifies repo/pr rows expose identifying
72	// fields from the raw payload, so trimmed views (e.g. --compact) don't collapse
73	// them to just {id, type, score}.
74	func TestResultAccessors_RawDataFallback(t *testing.T) {
75		t.Parallel()
76	
77		const repoName = "backend"
78	
79		var repoRow Result
80		if err := json.Unmarshal([]byte(`{"type":"repo","data":{"id":"01JREPO","name":"backend","org":"acme","createdAt":"2026-01-02T00:00:00Z"},"searchMeta":{"score":1}}`), &repoRow); err != nil {
81			t.Fatal(err)
82		}
83		if got := repoRow.ResultTitle(); got != repoName {
84			t.Errorf("repo ResultTitle() = %q, want \"backend\"", got)
85		}
86		if got := repoRow.ResultRepo(); got != repoName {
87			t.Errorf("repo ResultRepo() = %q, want \"backend\"", got)
88		}
89		if got := repoRow.ResultOrg(); got != "acme" {
90			t.Errorf("repo ResultOrg() = %q, want \"acme\"", got)
91		}
92		if got := repoRow.ResultCreatedAt(); got != "2026-01-02T00:00:00Z" {
93			t.Errorf("repo ResultCreatedAt() = %q", got)
94		}
95	
96		// A row carrying only an owner-qualified fullName splits into org + bare
97		// repo, so org+"/"+repo joins never double the owner (acme/acme/backend).
98		var qualifiedRow Result
99		if err := json.Unmarshal([]byte(`{"type":"repo","data":{"id":"01JQUAL","fullName":"acme/backend"},"searchMeta":{"score":1}}`), &qualifiedRow); err != nil {
100			t.Fatal(err)
101		}
102		if got := qualifiedRow.ResultOrg(); got != "acme" {
103			t.Errorf("fullName-only ResultOrg() = %q, want \"acme\"", got)
104		}
105		if got := qualifiedRow.ResultRepo(); got != repoName {
106			t.Errorf("fullName-only ResultRepo() = %q, want bare \"backend\"", got)
107		}
