111			t.Fatal(err)
112		}
113		if got := prRow.ResultTitle(); got != "Fix login retry" {
114			t.Errorf("pr ResultTitle() = %q, want \"Fix login retry\"", got)
115		}
116		if got := prRow.ResultRepo(); got != repoName {
117			t.Errorf("pr ResultRepo() = %q, want \"backend\"", got)
118		}
119		if got := prRow.ResultAuthor(); got != testAuthor {
120			t.Errorf("pr ResultAuthor() = %q, want \"alice\"", got)
121		}
122		if got := prRow.ResultBranch(); got != "fix/login" {
