399		if !strings.Contains(out, "\x1b[") {
400			t.Errorf("expected ANSI codes in highlighted output, got %q", out)
401		}
402		if !strings.HasPrefix(out, "func ") || !strings.HasSuffix(out, "(w)") {
403			t.Errorf("expected unmatched text preserved around highlight, got %q", out)
404		}
405	
406		if out := highlightCodeMatches("no match here", "zzz", styles, false); out != "no match here" {
407			t.Errorf("expected unchanged line when no match, got %q", out)
408		}
409	
410		// Case-sensitive search must not highlight case variants.
411		if out := highlightCodeMatches("func HandleRequest(w)", "handlerequest", styles, true); out != "func HandleRequest(w)" {
412			t.Errorf("expected no highlight for case mismatch with caseSensitive, got %q", out)
413		}
414	
415		// Non-ASCII input falls back to exact matching (no case folding).
416		if out := highlightCodeMatches("comment ÉTÉ ici", "été", styles, false); out != "comment ÉTÉ ici" {
417			t.Errorf("expected no case-folded highlight for non-ASCII input, got %q", out)
418		}
419		if out := highlightCodeMatches("comment été ici", "été", styles, false); !strings.Contains(out, "\x1b[") {
420			t.Errorf("expected exact non-ASCII match highlighted, got %q", out)
421		}
422	
423		plain := statusStyles{colorEnabled: false}
424		if out := highlightCodeMatches("func main()", "main", plain, false); out != "func main()" {
425			t.Errorf("expected unchanged line when color disabled, got %q", out)
426		}
427	}
