690		t.Parallel()
691	
692		// A US-homed repo with an EU mirror indexes the same content, so the
693		// fan-out queries both cells and each returns the SAME matches. Merged
694		// results dedupe by repo+path+line; the stats must dedupe too, or the
695		// summary reports "6 matches across 4 files in 2 repos" for 3 unique
696		// results (and falsely claims truncation). Regression guard for the
697		// mirror fan-out this trail introduced.
698		matches := []codesearch.Result{
699			{Repo: "acme/web", Path: "main.go", Line: 1, Column: 0, Score: 0.9},
700			{Repo: "acme/web", Path: "main.go", Line: 2, Column: 0, Score: 0.8},
