702		}
703		cell := func(name, jur string) cellCallResult[*codesearch.SearchResponse] {
704			return cellCallResult[*codesearch.SearchResponse]{
705				group: cellGroup{cell: name, jurisdiction: jur},
706				value: &codesearch.SearchResponse{
707					Query:     "handleRequest",
708					Stats:     codesearch.Stats{TotalMatches: 3, TotalFiles: 2, ReposSearched: 1, DurationMs: 10},
709					RepoStats: []codesearch.RepoStats{{Repo: "acme/web", MatchCount: 3, FileCount: 2}},
710					Results:   matches,
711				},
712			}
713		}
714		results := []cellCallResult[*codesearch.SearchResponse]{
715			cell("aws-us-east-2", "us"),
716			cell(testCellEU, "eu"),
717		}
718	
719		merged, err := mergeSearchResults(context.Background(), 0, results)
720		if err != nil {
721			t.Fatalf("unexpected error: %v", err)
722		}
723		if len(merged.Results) != 3 {
724			t.Fatalf("len(Results) = %d, want 3 (mirror duplicates removed)", len(merged.Results))
725		}
726		if merged.Stats.TotalMatches != 3 {
727			t.Errorf("TotalMatches = %d, want 3 (mirror must not double-count)", merged.Stats.TotalMatches)
728		}
729		if merged.Stats.TotalFiles != 2 {
730			t.Errorf("TotalFiles = %d, want 2 (mirror must not double-count)", merged.Stats.TotalFiles)
731		}
732		if merged.Stats.ReposSearched != 1 {
733			t.Errorf("ReposSearched = %d, want 1 (one logical repo across two cells)", merged.Stats.ReposSearched)
734		}
735		if merged.Stats.DurationMs != 10 {
736			t.Errorf("DurationMs = %v, want 10 (slowest cell preserved)", merged.Stats.DurationMs)
737		}
738		if len(merged.RepoStats) != 1 {
739			t.Fatalf("len(RepoStats) = %d, want 1 (deduped by repo)", len(merged.RepoStats))
740		}
741		if merged.RepoStats[0].MatchCount != 3 || merged.RepoStats[0].FileCount != 2 {
742			t.Errorf("RepoStats[0] = %+v, want representative {3,2} not summed {6,4}", merged.RepoStats[0])
743		}
744	}
